patches.before:
/* Dashboard-only visual design; other modules remain unchanged. */
body.humbel-home-mode{background:#f3f6fb;color:#102033}
body.humbel-home-mode #tabs{position:fixed;top:0;bottom:0;left:0;width:238px;z-index:45;background:linear-gradient(160deg,#071d35,#0b2a4b);display:flex!important;flex-direction:column;flex-wrap:nowrap;gap:7px;padding:85px 10px 22px;overflow-y:auto;box-shadow:4px 0 18px #061e351a}
body.humbel-home-mode #tabs:before{content:"⚙  Humbel-App";position:absolute;top:20px;left:18px;color:white;font-size:21px;font-weight:800}
body.humbel-home-mode #tabs button{width:100%;text-align:left;color:#f1f6ff;background:transparent;border:0;border-radius:10px;min-height:48px;padding:12px 14px;font-weight:600}
body.humbel-home-mode #tabs button:hover,body.humbel-home-mode #tabs .humbel-main-tab-active{background:#095ba6;color:white}
body.humbel-home-mode #tabs button:last-child{margin-top:auto;background:#24415c}
body.humbel-home-mode #tabs + #personal-production-times{margin-left:238px}
body.humbel-home-mode #view{margin-left:238px}
body.humbel-home-mode #view>div{max-width:none}

.humbel-main-nav {
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--humbel-border);
  border-radius: 12px;
  padding: 8px;
  box-shadow: 0 10px 26px rgba(13, 70, 130, 0.06);
}

.humbel-main-tab,
.humbel-subtab {
  background: #ffffff !important;
  color: var(--humbel-blue-dark) !important;
  border-color: var(--humbel-border) !important;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(16, 32, 51, 0.04);
}

.humbel-main-tab:hover,
.humbel-subtab:hover {
  background: #eef5fb !important;
  border-color: rgba(13, 70, 130, 0.34) !important;
}

.humbel-main-tab-active,
.humbel-subtab-active {
  background: var(--humbel-blue) !important;
  color: #ffffff !important;
  border-color: var(--humbel-blue) !important;
  box-shadow: 0 8px 20px rgba(13, 70, 130, 0.22);
}

.humbel-tab-attention {
  border-color: #fb7185 !important;
}
